import { Platform } from "react-native";
import { buildPack, decode, parseFacts, findFacts, words, type Fact, type Pack, type Question } from "@bayanihan/bayani";
import FACTS from "@/data/facts.json";
import type { R } from "./bix";
import { completionFor, confidenceOf, type TokenProbs } from "./bayaniPrompt";

/*
 * Bayani in the app (bayani repo: docs/CONTEXT_PACK.md, knowledge/README.md).
 * - Facts: looked up and shown as written, on every phone and the web. Never generated by the model.
 * - The model: Bayani-1 (SmolLM2-1.7B Q4 + the Bayani LoRA add-on), native Android/iOS only, an optional download.
 *   It was trained on BIX records, not on text. It is not a chat model and never writes open answers (Don, 2026-11-15).
 *   It makes judgments about BIX records, held to a fixed set of answers by a grammar; now one: is this step the same
 *   kind of step as a usual one? The copilot (lib/copilot.ts) turns records, rules and those judgments into moves.
 */

void parseFacts;
export const facts = FACTS as Fact[];
/** The best facts for a question; a weak match is not an answer. */
export function ask(question: string) {
  const found = findFacts(question, facts, 3);
  return found.filter((f) => f.score >= Math.max(3, (found[0]?.score ?? 0) * 0.6));
}

const HF = "https://huggingface.co/dasig/bayani-1/resolve/main";
const FILES = { base: { name: "base-q4_k_m.gguf", mb: 1056 }, lora: { name: "bayani-1-lora.gguf", mb: 36 } } as const;
export const MODEL_MB = FILES.base.mb + FILES.lora.mb;
export const modelSupported = Platform.OS !== "web";

async function fs() {
  const FS = await import("expo-file-system");
  const dir = new FS.Directory(FS.Paths.document, "bayani");
  if (!dir.exists) dir.create({ intermediates: true, idempotent: true });
  return { FS, dir, file: (k: keyof typeof FILES) => new FS.File(dir, FILES[k].name) };
}

export async function modelDownloaded(): Promise<boolean> {
  if (!modelSupported) return false;
  const { file } = await fs();
  return (["base", "lora"] as const).every((k) => file(k).exists && (file(k).size ?? 0) > FILES[k].mb * 900_000);
}

/**
 * Download both files (about 1.1 GB), to their exact names, with progress (0–1). Use Wi-Fi.
 * 2026-11-14: File.downloadFileAsync into the folder named the file after Hugging Face's redirect URL, so it was never
 * found, and showed no progress. Now the legacy resumable download, which writes to the given path and reports bytes.
 */
export async function downloadModel(onProgress?: (share: number) => void): Promise<void> {
  const { file } = await fs();
  const L = await import("expo-file-system/legacy");
  const total = MODEL_MB * 1_000_000;
  let before = 0;
  for (const k of ["lora", "base"] as const) {
    if (file(k).exists && (file(k).size ?? 0) > FILES[k].mb * 900_000) { before += FILES[k].mb * 1_000_000; onProgress?.(before / total); continue; }
    if (file(k).exists) file(k).delete();
    const dl = L.createDownloadResumable(`${HF}/${FILES[k].name}`, file(k).uri, {}, (p) => onProgress?.(Math.min(1, (before + p.totalBytesWritten) / total)));
    const r = await dl.downloadAsync();
    if (!r || r.status >= 400) { if (file(k).exists) file(k).delete(); throw new Error(`The download stopped (${r?.status ?? "no answer"}). Try again on Wi-Fi.`); }
    before += FILES[k].mb * 1_000_000;
  }
}

export async function removeModel(): Promise<void> {
  ctx = null;
  const { file } = await fs();
  for (const k of ["base", "lora"] as const) if (file(k).exists) file(k).delete();
}

type Ctx = {
  completion: (p: Record<string, unknown>, cb?: (d: { token: string }) => void) => Promise<{ text: string }>;
  stopCompletion: () => Promise<void>;
  applyLoraAdapters: (l: { path: string; scaled?: number }[]) => Promise<void>;
  removeLoraAdapters: () => Promise<void>;
};
let loraOn = false;
let ctx: Ctx | null = null;
const path = (uri: string) => uri.replace(/^file:\/\//, "");

async function model(): Promise<Ctx | null> {
  if (ctx) return ctx;
  if (!(await modelDownloaded())) return null;
  const { file } = await fs();
  const { initLlama } = await import("llama.rn");
  ctx = (await initLlama({ model: path(file("base").uri), n_ctx: 2048 })) as unknown as Ctx;
  loraOn = false;
  return ctx;
}
async function lora(m: Ctx, on: boolean) {
  if (on === loraOn) return;
  if (on) { const { file } = await fs(); await m.applyLoraAdapters([{ path: path(file("lora").uri), scaled: 1 }]); } else await m.removeLoraAdapters();
  loraOn = on;
}

/** Who suggested it, as BIX Provenance names a model (rule 3, "Suggestions and their answers"). */
export const MODEL = { name: "Bayani-1", version: "1.7B-q4-lora-2026-11-14" } as const;
/**
 * Below this, a judgment isn't shown (BIX leaves thresholds to the app). Set from scripts/bayani-check.ts (2026-11-15,
 * the 254 held-out questions through this app's prompt, grammar and confidence, llama.cpp): at 0.8 the shown answers
 * were right 98% (same step), 97% (which usual step), 94% (which team), 100% (belongs, one-off), and 93% were shown;
 * at 0.6, which team was 90%. Synthetic, tidy data: check again on a real group's projects.
 */
export const SHOW_AT = 0.8;

export type Judgment =
  | { kind: "yes-no"; value: boolean; confidence: number; question: Question["kind"] }
  | { kind: "reference"; value: string | null; confidence: number; question: Question["kind"] }
  | { kind: "text"; value: string; confidence: number; question: Question["kind"] };

// One question at a time: the phone has one model context. Answers are kept for the same records (by version).
let queue: Promise<unknown> = Promise.resolve();
const serial = <T,>(f: () => Promise<T>): Promise<T> => { const run = queue.then(f, f); queue = run.catch(() => undefined); return run; };
const cache = new Map<string, Judgment | null>();
const keyOf = (q: Question, records: R[]) => JSON.stringify(q) + "|" + records.map((r) => `${r.resourceType}/${r.id}@${r.meta?.version ?? 0}`).sort().join(",");

/**
 * One of the six questions Bayani-1 was trained on (bayani README, "The questions Bayani-1 is trained on"), asked in
 * exactly the training format: the pack is built by the bayani package from BIX records (`buildPack`), so the app and
 * the training data can't drift apart. Fixed answers are held to the allowed list by a grammar; the confidence is the
 * raw softmax of the answer's first token over the allowed first tokens (`post_sampling_probs: false`). A general
 * title is the only text, under a grammar, at most 60 characters. Null when the model isn't on this phone, or when
 * the answer is known without it.
 * `records`: what this person's server gave them (already filtered for them, rule 26), including the project, its
 * teams, its steps and the group's Practices.
 */
export async function judge(q: Question, records: R[], viewer: string): Promise<Judgment | null> {
  if (!modelSupported) return null;
  const key = keyOf(q, records);
  if (cache.has(key)) return cache.get(key)!;
  let pack: Pack;
  try { pack = buildPack(q, { records: records as never, viewer, now: new Date().toISOString(), prefiltered: true, maxTokens: 600 }); } catch { return null; }
  if (!pack.needsModel) return null;
  const out = await serial(async (): Promise<Judgment | null> => {
    const m = await model();
    if (!m) return null;
    await lora(m, true);
    const r = (await m.completion(completionFor(pack))) as { text: string; completion_probabilities?: TokenProbs };
    const d = decode(pack, r.text);
    if (!d.ok) return null;
    const confidence = confidenceOf(pack, r.completion_probabilities);
    return { ...d, confidence, question: q.kind } as Judgment;
  }).catch(() => null);
  cache.set(key, out);
  return out;
}
/** How a person's answer to a model suggestion is recorded (BIX "Suggestions and their answers"). */
export const assisted = (j: Judgment, edited = false) => ({ type: "model" as const, model: { ...MODEL, question: j.question, ...(Number.isFinite(j.confidence) ? { confidence: Math.round(j.confidence * 100) / 100 } : {}), ...(edited ? { edited: true } : {}) } });

/** The existing step most likely to be the same as a usual one: shared words, plus a point for the same team. */
export function closestTask(practice: R, tasks: R[], teamName: (t: R) => string | undefined): R | null {
  const pw = words(String(practice.title ?? ""));
  let best: R | null = null, score = 0;
  for (const t of tasks) {
    if (t.status === "cancelled") continue;
    const shared = [...words(String(t.title ?? ""))].filter((w) => pw.has(w)).length;
    const s = shared * 2 + (String(teamName(t) ?? "").toLowerCase() === String(practice.team ?? "").toLowerCase() && practice.team ? 1 : 0);
    if (s > score) { score = s; best = t; }
  }
  return best;
}
